     1	// Bun test preload: mock the server-only sentinel package (which throws outside
     2	// a server component context) and stub external service dependencies (database,
     3	// email, observability) to avoid real network/DB calls in tests.
     4	// ABSTRACT_API_KEY is intentionally empty so the deliverability API layer is
     5	// bypassed in all tests (fail-open behavior).
     6	import { mock } from "bun:test";
     7	
     8	// Set process.env fallbacks for required env vars. Bun's mock.module does not
     9	// reliably intercept dynamic imports using path aliases (@/env), so when the
    10	// real env.ts loads transitively it needs valid values to pass t3-env validation.
    11	process.env.MONGODB_URI ??= "mongodb://localhost:27017/test";
    12	process.env.RESEND_FROM ??= "[REDACTED_EMAIL]";
    13	process.env.RESEND_TOKEN ??= "re_test_token";
    14	process.env.RESEND_SEGMENT_ID ??= "test-segment-id";
    15	process.env.RESEND_WEBHOOK_SECRET ??= "REDACTED";
    16	process.env.RECONCILE_SECRET ??= "test-reconcile-secret-that-is-long-enough";
    17	process.env.NEXT_PUBLIC_APP_URL ??= "http://localhost:3000";
    18	process.env.NEXT_PUBLIC_WEB_URL ??= "http://localhost:3001";
    19	process.env.NEXT_PUBLIC_POSTHOG_HOST ??= "https://eu.i.posthog.com";
    20	process.env.NEXT_PUBLIC_POSTHOG_KEY ??= "phc_test";
    21	
    22	mock.module("server-only", () => ({}));
    23	
    24	mock.module("@/env", () => ({
    25	  env: {
    26	    ABSTRACT_API_KEY: "",
    27	    NEXT_PUBLIC_APP_URL: "http://localhost:3000",
    28	    NEXT_PUBLIC_WEB_URL: "http://localhost:3001",
    29	    RECONCILE_SECRET: "test-reconcile-secret-that-is-long-enough",
    30	    RESEND_FROM: "[REDACTED_EMAIL]",
    31	    RESEND_SEGMENT_ID: "test-segment-id",
    32	  },
    33	}));
    34	
    35	mock.module("@repo/database", () => ({
    36	  createId: () => "test-id",
    37	  database: {
    38	    subscriber: {
    39	      deleteMany: async () => ({ deletedCount: 0 }),
    40	      deleteOne: async () => ({ deletedCount: 0 }),
    41	      find: () => ({ toArray: async () => [] }),
    42	      findOne: async () => null,
    43	      updateOne: async () => ({}),
    44	    },
    45	  },
    46	}));
    47	
    48	mock.module("@repo/email", () => ({
    49	  resend: {
    50	    contacts: {
    51	      create: async () => ({ data: { id: "contact-id" }, error: null }),
    52	      list: async () => ({
    53	        data: { data: [], has_more: false, object: "list" },
    54	        error: null,
    55	      }),
    56	      remove: async () => ({ error: null }),
    57	    },
    58	    emails: { send: async () => ({ error: null }) },
    59	    webhooks: {
    60	      verify: () => {
    61	        throw new Error("No signature");
    62	      },
    63	    },
    64	  },
    65	}));
    66	
