     1	import { afterEach, describe, expect, spyOn, test } from "bun:test";
     2	import { database } from "@repo/database";
     3	import { resend } from "@repo/email";
     4	import { NextRequest } from "next/server";
     5	import { resetRateLimiters } from "@/lib/rate-limit";
     6	import { POST } from "./route";
     7	
     8	const DAY_MS = 1000 * 60 * 60 * 24;
     9	const SUCCESS = "Check your inbox. One click confirms it.";
    10	
    11	// The preload mocks @repo/database and @repo/email once for every test file;
    12	// spying on those shared objects keeps this file's behaviour from leaking.
    13	const findOne = spyOn(database.subscriber, "findOne");
    14	const updateOne = spyOn(database.subscriber, "updateOne");
    15	const send = spyOn(resend.emails, "send");
    16	const createContact = spyOn(resend.contacts, "create");
    17	
    18	afterEach(() => {
    19	  resetRateLimiters();
    20	  findOne.mockReset();
    21	  updateOne.mockReset();
    22	  send.mockReset();
    23	  createContact.mockReset();
    24	});
    25	
    26	function makeRequest(body: Record<string, unknown>) {
    27	  return new NextRequest("http://localhost:3001/api/confirm", {
    28	    body: JSON.stringify(body),
    29	    headers: { "Content-Type": "application/json" },
    30	    method: "POST",
    31	  });
    32	}
    33	
    34	function subscriber(overrides: Record<string, unknown>) {
    35	  return {
    36	    _id: "sub-1",
    37	    createdAt: new Date(),
    38	    email: "[REDACTED_EMAIL]",
    39	    emailVerified: null,
    40	    image: null,
    41	    name: null,
    42	    role: "user",
    43	    token: "old-hash",
    44	    tokenExpiresAt: null,
    45	    ...overrides,
    46	  };
    47	}
    48	
    49	function post(existing: ReturnType<typeof subscriber> | null, email: string) {
    50	  findOne.mockResolvedValue(existing as never);
    51	  updateOne.mockResolvedValue({} as never);
    52	  send.mockResolvedValue({ data: { id: "email-id" }, error: null } as never);
    53	  createContact.mockResolvedValue({
    54	    data: { id: "contact-id" },
    55	    error: null,
    56	  } as never);
    57	  return POST(makeRequest({ email }));
    58	}
    59	
    60	function sentSubjects() {
    61	  return send.mock.calls.map(([payload]) => payload.subject);
    62	}
    63	
    64	describe("/api/confirm", () => {
    65	  test("rejects disposable email addresses", async () => {
    66	    const response = await POST(makeRequest({ email: "[REDACTED_EMAIL]" }));
    67	    const data = await response.json();
    68	    expect(response.status).toBe(400);
    69	    expect(data.error.message).toContain("doesn't look quite right");
    70	  });
    71	
    72	  test("rejects invalid email format", async () => {
    73	    const response = await POST(makeRequest({ email: "not-an-email" }));
    74	    expect(response.status).toBe(400);
    75	  });
    76	
    77	  test("sends a confirmation to an address it has never seen", async () => {
    78	    const response = await post(null, "[REDACTED_EMAIL]");
    79	    expect(response.status).toBe(200);
    80	    expect((await response.json()).message).toBe(SUCCESS);
    81	    expect(sentSubjects()).toEqual(["One click and you’re on the waitlist"]);
    82	    expect(send.mock.calls[0]?.[0].to).toEqual(["[REDACTED_EMAIL]"]);
    83	    expect(updateOne.mock.calls[0]?.[2]).toEqual({ upsert: true });
    84	  });
    85	
    86	  test("normalizes the address before looking it up and sending", async () => {
    87	    await post(null, "  [REDACTED_EMAIL] ");
    88	    expect(findOne.mock.calls[0]?.[0]).toEqual({ email: "[REDACTED_EMAIL]" });
    89	    expect(updateOne.mock.calls[0]?.[0]).toEqual({ email: "[REDACTED_EMAIL]" });
    90	    expect(send.mock.calls[0]?.[0].to).toEqual(["[REDACTED_EMAIL]"]);
    91	  });
    92	
    93	  test("stays quiet when an unconfirmed address resubmits within the cooldown", async () => {
    94	    const issuedSecondsAgo = 30;
    95	    const response = await post(
    96	      subscriber({
    97	        tokenExpiresAt: new Date(Date.now() + DAY_MS - issuedSecondsAgo * 1000),
    98	      }),
    99	      "[REDACTED_EMAIL]"
   100	    );
   101	    expect(response.status).toBe(200);
   102	    expect((await response.json()).message).toBe(SUCCESS);
   103	    expect(send).not.toHaveBeenCalled();
   104	    expect(updateOne).not.toHaveBeenCalled();
   105	  });
   106	
   107	  test("resends with a fresh token once the cooldown has passed", async () => {
   108	    const issuedMinutesAgo = 10;
   109	    const response = await post(
   110	      subscriber({
   111	        tokenExpiresAt: new Date(
   112	          Date.now() + DAY_MS - issuedMinutesAgo * 60 * 1000
   113	        ),
   114	      }),
   115	      "[REDACTED_EMAIL]"
   116	    );
   117	    expect(response.status).toBe(200);
   118	    expect(sentSubjects()).toEqual(["One click and you’re on the waitlist"]);
   119	    const setFields = updateOne.mock.calls[0]?.[1] as {
   120	      $set: { token: string };
   121	    };
   122	    expect(setFields.$set.token).not.toBe("old-hash");
   123	  });
   124	
   125	  test("resends when the earlier link has already expired", async () => {
   126	    await post(
   127	      subscriber({ tokenExpiresAt: new Date(Date.now() - DAY_MS) }),
   128	      "[REDACTED_EMAIL]"
   129	    );
   130	    expect(sentSubjects()).toEqual(["One click and you’re on the waitlist"]);
   131	  });
   132	
   133	  test("tells a confirmed address it is already on the list", async () => {
   134	    const response = await post(
   135	      subscriber({ emailVerified: new Date(), tokenExpiresAt: null }),
   136	      "[REDACTED_EMAIL]"
   137	    );
   138	    expect(response.status).toBe(200);
   139	    expect((await response.json()).message).toBe(SUCCESS);
   140	    expect(sentSubjects()).toEqual(["You’re already on the waitlist"]);
   141	    expect(updateOne).not.toHaveBeenCalled();
   142	  });
   143	
   144	  test("puts a confirmed address back into the Resend segment", async () => {
   145	    await post(
   146	      subscriber({ emailVerified: new Date(), tokenExpiresAt: null }),
   147	      "[REDACTED_EMAIL]"
   148	    );
   149	    expect(createContact.mock.calls[0]?.[0] as unknown).toEqual({
   150	      email: "[REDACTED_EMAIL]",
   151	      segments: [{ id: "test-segment-id" }],
   152	      unsubscribed: false,
   153	    });
   154	  });
   155	});
   156	
   157	function postFrom(email: string, ip: string) {
   158	  findOne.mockResolvedValue(null as never);
   159	  updateOne.mockResolvedValue({} as never);
   160	  send.mockResolvedValue({ data: { id: "x" }, error: null } as never);
   161	  return POST(
   162	    new NextRequest("http://localhost:3001/api/confirm", {
   163	      body: JSON.stringify({ email }),
   164	      headers: { "Content-Type": "application/json", "x-real-ip": ip },
   165	      method: "POST",
   166	    })
   167	  );
   168	}
   169	
   170	// The window counts requests in order, so these cannot run in parallel.
   171	function postSequence(
   172	  count: number,
   173	  make: (i: number) => Promise<Response>
   174	): Promise<number[]> {
   175	  return Array.from({ length: count }, (_, i) => i).reduce<Promise<number[]>>(
   176	    async (previous, i) => [...(await previous), (await make(i)).status],
   177	    Promise.resolve([])
   178	  );
   179	}
   180	
   181	describe("/api/confirm legacy casing", () => {
   182	  const duplicateKey = Object.assign(new Error("E11000 duplicate key"), {
   183	    code: 11_000,
   184	  });
   185	
   186	  test("looks the address up under the index collation", async () => {
   187	    await post(null, "[REDACTED_EMAIL]");
   188	    expect(findOne.mock.calls[0]?.[1]).toEqual({
   189	      collation: { locale: "en", strength: 2 },
   190	    });
   191	  });
   192	
   193	  test("retries a rejected upsert against the legacy row and sends", async () => {
   194	    findOne.mockResolvedValue(null as never);
   195	    updateOne
   196	      .mockRejectedValueOnce(duplicateKey as never)
   197	      .mockResolvedValueOnce({ matchedCount: 1 } as never);
   198	    send.mockResolvedValue({ data: { id: "x" }, error: null } as never);
   199	
   200	    const response = await POST(makeRequest({ email: "[REDACTED_EMAIL]" }));
   201	
   202	    expect(response.status).toBe(200);
   203	    expect(updateOne).toHaveBeenCalledTimes(2);
   204	    expect(updateOne.mock.calls[1]?.[2]).toEqual({
   205	      collation: { locale: "en", strength: 2 },
   206	    });
   207	    expect(sentSubjects()).toEqual(["One click and you’re on the waitlist"]);
   208	  });
   209	
   210	  test("fails rather than mail a token no row holds", async () => {
   211	    findOne.mockResolvedValue(null as never);
   212	    updateOne
   213	      .mockRejectedValueOnce(duplicateKey as never)
   214	      .mockResolvedValueOnce({ matchedCount: 0 } as never);
   215	
   216	    const response = await POST(makeRequest({ email: "[REDACTED_EMAIL]" }));
   217	
   218	    expect(response.status).toBe(500);
   219	    expect(send).not.toHaveBeenCalled();
   220	  });
   221	
   222	  test("lets any other database error through as a 500", async () => {
   223	    findOne.mockResolvedValue(null as never);
   224	    updateOne.mockRejectedValueOnce(new Error("connection reset") as never);
   225	
   226	    const response = await POST(makeRequest({ email: "[REDACTED_EMAIL]" }));
   227	
   228	    expect(response.status).toBe(500);
   229	    expect(updateOne).toHaveBeenCalledTimes(1);
   230	  });
   231	});
   232	
   233	describe("/api/confirm limits", () => {
   234	  test("refuses a caller that floods the form with fresh addresses", async () => {
   235	    const ip = "198.51.100.7";
   236	    const statuses = await postSequence(12, (i) =>
   237	      postFrom(`flood-${i}@example.com`, ip)
   238	    );
   239	    expect(statuses.at(-1)).toBe(429);
   240	    expect(send.mock.calls.length).toBeLessThan(12);
   241	  });
   242	
   243	  test("refuses repeated mail to one address across callers", async () => {
   244	    const statuses = await postSequence(4, (i) =>
   245	      postFrom("[REDACTED_EMAIL]", `192.0.2.${i}`)
   246	    );
   247	    expect(statuses.at(-1)).toBe(429);
   248	    expect(send.mock.calls.length).toBe(3);
   249	  });
   250	
   251	  test("builds the confirmation link on the configured site for a foreign host", async () => {
   252	    findOne.mockResolvedValue(null as never);
   253	    updateOne.mockResolvedValue({} as never);
   254	    send.mockResolvedValue({ data: { id: "x" }, error: null } as never);
   255	    await POST(
   256	      new NextRequest("https://evil.example/api/confirm", {
   257	        body: JSON.stringify({ email: "[REDACTED_EMAIL]" }),
   258	        headers: { "Content-Type": "application/json" },
   259	        method: "POST",
   260	      })
   261	    );
   262	    const react = send.mock.calls[0]?.[0].react as {
   263	      props: { baseUrl: string };
   264	    };
   265	    expect(react.props.baseUrl).toBe("http://localhost:3001");
   266	  });
   267	});
