     1	import { afterEach, describe, expect, spyOn, test } from "bun:test";
     2	import { database } from "@repo/database";
     3	import { resend } from "@repo/email";
     4	import { NextRequest } from "next/server";
     5	import { orphansLookWrong, POST } from "./route";
     6	
     7	const SECRET = "test-reconcile-secret-that-is-long-enough";
     8	
     9	const list = spyOn(resend.contacts, "list");
    10	const removeContact = spyOn(resend.contacts, "remove");
    11	const find = spyOn(database.subscriber, "find");
    12	const deleteMany = spyOn(database.subscriber, "deleteMany");
    13	
    14	afterEach(() => {
    15	  for (const spy of [list, removeContact, find, deleteMany]) {
    16	    spy.mockReset();
    17	  }
    18	});
    19	
    20	function post(authorization?: string) {
    21	  return POST(
    22	    new NextRequest("http://localhost:3001/api/reconcile", {
    23	      headers: authorization ? { authorization } : {},
    24	      method: "POST",
    25	    })
    26	  );
    27	}
    28	
    29	describe("orphansLookWrong", () => {
    30	  test("refuses an empty listing while subscribers exist", () => {
    31	    expect(orphansLookWrong(40, 0, 40)).toBe(true);
    32	  });
    33	
    34	  test("allows a handful of departures on a small list", () => {
    35	    expect(orphansLookWrong(6, 1, 5)).toBe(false);
    36	    expect(orphansLookWrong(6, 1, 6)).toBe(true);
    37	  });
    38	
    39	  test("refuses losing more than half of a large list at once", () => {
    40	    expect(orphansLookWrong(1000, 400, 500)).toBe(false);
    41	    expect(orphansLookWrong(1000, 400, 501)).toBe(true);
    42	  });
    43	
    44	  test("an empty database has nothing to protect", () => {
    45	    expect(orphansLookWrong(0, 0, 0)).toBe(false);
    46	  });
    47	});
    48	
    49	describe("/api/reconcile", () => {
    50	  test("refuses to delete anyone when Resend lists no contacts", async () => {
    51	    list.mockResolvedValue({
    52	      data: { data: [], has_more: false, object: "list" },
    53	      error: null,
    54	    } as never);
    55	    find.mockReturnValue({
    56	      toArray: () =>
    57	        Promise.resolve([
    58	          { email: "[REDACTED_EMAIL]" },
    59	          { email: "[REDACTED_EMAIL]" },
    60	        ]),
    61	    } as never);
    62	
    63	    const response = await post(`Bearer ${SECRET}`);
    64	
    65	    expect(response.status).toBe(409);
    66	    expect(deleteMany).not.toHaveBeenCalled();
