    68	
    69	  test("rejects a missing or wrong bearer token", async () => {
    70	    expect((await post()).status).toBe(401);
    71	    expect((await post("Bearer nope")).status).toBe(401);
    72	    expect(list).not.toHaveBeenCalled();
    73	  });
    74	
    75	  test("removes flagged, orphaned and stale unconfirmed subscribers", async () => {
    76	    list.mockResolvedValue({
    77	      data: {
    78	        data: [
    79	          { email: "[REDACTED_EMAIL]", id: "c1", unsubscribed: false },
    80	          { email: "[REDACTED_EMAIL]", id: "c2", unsubscribed: true },
    81	        ],
    82	        has_more: false,
    83	        object: "list",
    84	      },
    85	      error: null,
    86	    } as never);
    87	    removeContact.mockResolvedValue({ data: null, error: null } as never);
    88	    find.mockReturnValue({
    89	      toArray: () =>
    90	        Promise.resolve([
    91	          { email: "[REDACTED_EMAIL]" },
    92	          { email: "[REDACTED_EMAIL]" },
