    94	        ]),
    95	    } as never);
    96	    // Per-address erasures answer 1; the stale-unconfirmed sweep answers 2.
    97	    deleteMany.mockImplementation(((filter: { email?: string }) =>
    98	      Promise.resolve({ deletedCount: filter.email ? 1 : 2 })) as never);
    99	
   100	    const response = await post(`Bearer ${SECRET}`);
