     1	/**
     2	 * Where the confirmation link points. The request's own origin is what a
     3	 * preview deployment or a local run needs — the token is in that database
     4	 * — but it comes from the Host header, which anything can send. So the
     5	 * request origin is honoured only when its host is the configured site,
     6	 * one of this deployment's own hostnames (VERCEL_URL and VERCEL_BRANCH_URL,
     7	 * set by the platform), or localhost. Any other host, including someone
     8	 * else's *.vercel.app, gets the configured origin.
     9	 */
    10	export function confirmationOrigin(
    11	  requestUrl: string,
    12	  configuredUrl: string,
    13	  deploymentHosts: readonly (string | undefined)[] = [
    14	    process.env.VERCEL_URL,
    15	    process.env.VERCEL_BRANCH_URL,
    16	  ]
    17	): string {
    18	  const configured = new URL(configuredUrl).origin;
    19	  let request: URL;
    20	  try {
    21	    request = new URL(requestUrl);
    22	  } catch {
    23	    return configured;
    24	  }
