    37	  const prune = (stamps: number[], cutoff: number) => {
    38	    let i = 0;
    39	    while (i < stamps.length && (stamps[i] as number) <= cutoff) {
    40	      i += 1;
    41	    }
    42	    return i === 0 ? stamps : stamps.slice(i);
    43	  };
