    55	    actionId: incoming.get("next-action") ?? "",
    56	    contentType: (incoming.get("content-type") ?? "").split(";")[0],
    57	    count,
    58	    path: pathnameOf(incoming.get("referer")),
    59	    setCookie: `${COUNT_COOKIE}=${count}; Path=${options.path}; Max-Age=${options.maxAge}; HttpOnly; SameSite=Lax`,
