    60	// matcher excludes these, but proxy.ts runs it for all matched routes via
    61	// createNEMO, causing rewrites to /en/... paths that don't exist). The two
    62	// metadata files live at the app root, where Next serves them from.
    63	const UNLOCALIZED = new Set(["/robots.txt", "/sitemap.xml"]);
