9	/**
10	 * The safety net under the webhook. Called on a schedule (an Atlas trigger),
11	 * it makes the two stores agree with the privacy policy again:
12	 *
13	 * - a contact Resend has flagged `unsubscribed` is deleted from both stores;
14	 * - a confirmed subscriber Resend no longer knows (deleted in the dashboard,
15	 *   webhook missed) is deleted here too;
16	 * - a signup that never confirmed is dropped once its link has been dead
17	 *   for a week — the address was collected for a confirmation that never
18	 *   came, so the purpose it was collected for has ended.
19	 */
20	const UNCONFIRMED_GRACE_MS = 1000 * 60 * 60 * 24 * 7;
21	const PAGE_SIZE = 100;
22	
23	/**
24	 * "Orphaned" means Resend no longer knows the address — but an empty or
25	 * truncated listing looks the same as a deliberate deletion. A wrong segment
26	 * id, an API that answers with no data and no error, or a partial page would
27	 * read as "everyone left" and empty the list. So a run that would orphan
28	 * more than this share of the confirmed subscribers is refused and reported,
29	 * and a listing that comes back empty while subscribers exist is never
30	 * trusted. Small lists get an absolute allowance so the first few departures
31	 * are still processed.
32	 */
33	const MAX_ORPHAN_SHARE = 0.5;
34	const MIN_ORPHAN_ALLOWANCE = 5;
35	
36	export function orphansLookWrong(
37	  confirmed: number,
38	  known: number,
39	  orphaned: number
40	): boolean {
41	  if (confirmed === 0) {
42	    return false;
43	  }
44	  if (known === 0) {
45	    return true;
46	  }
47	  const allowance = Math.max(
48	    MIN_ORPHAN_ALLOWANCE,
49	    Math.floor(confirmed * MAX_ORPHAN_SHARE)
50	  );
51	  return orphaned > allowance;
52	}
