7	/**
8	 * Resend reports list exits here. Broadcasts carry Resend's own unsubscribe
9	 * link, which marks the contact `unsubscribed` rather than deleting it —
10	 * this route turns that flag into the deletion the privacy policy promises.
11	 * Hard bounces and spam complaints leave the list the same way: Resend
12	 * suppresses them on its side, and the address must not linger on ours.
13	 *
14	 * Resend retries undelivered webhooks for about a day; the reconciliation
15	 * endpoint covers anything that slips past that.
16	 */
17	function emailsLeaving(event: WebhookEventPayload): string[] {
18	  switch (event.type) {
19	    case "contact.updated":
20	      return event.data.unsubscribed ? [event.data.email] : [];
21	    case "contact.deleted":
22	      return [event.data.email];
23	    case "email.bounced":
24	      return event.data.bounce.type === "Permanent" ? event.data.to : [];
25	    case "email.complained":
26	      return event.data.to;
27	    default:
28	      return [];
29	  }
30	}
