32	export async function POST(request: NextRequest) {
33	  const payload = await request.text();
34	
35	  let event: WebhookEventPayload;
36	  try {
37	    event = resend.webhooks.verify({
38	      headers: {
39	        id: request.headers.get("svix-id") ?? "",
40	        signature: request.headers.get("svix-signature") ?? "",
41	        timestamp: request.headers.get("svix-timestamp") ?? "",
42	      },
43	      payload,
44	      webhookSecret: keys().RESEND_WEBHOOK_SECRET,
45	    });
46	  } catch {
47	    return NextResponse.json({ error: "Invalid signature" }, { status: 400 });
48	  }
49	
50	  try {
51	    await Promise.all(emailsLeaving(event).map(removeSubscriber));
52	  } catch (error) {
53	    // A 500 makes Resend retry, which is what a failed deletion needs.
54	    after(() => parseError(error));
55	    return NextResponse.json({ error: "Removal failed" }, { status: 500 });
56	  }
57	
58	  return NextResponse.json({ received: true });
59	}
